"use strict";var SP_BODIES=[{k:"sun",name:"The Sun",kind:"Our star",orbit:0,ang:0,y:0,r:300,col:16762960,spin:.01,rows:[["Type","A yellow dwarf star (G2V)"],["Diameter","1,392,700 km: 109 Earths across"],["Surface","about 5,500 °C"],["Core","about 15 million °C"],["Age","about 4.6 billion years"],["Mass","99.86% of everything in the Solar System"]],notes:["Its light takes about 8 minutes 20 seconds to reach Earth.","It makes its energy by fusing hydrogen into helium in its core.","Never look straight at the real Sun: it can blind you."]},{k:"mercury",name:"Mercury",kind:"The first planet",orbit:1100,ang:.6,y:20,r:24,col:10130058,spin:.02,land:"mercury",rows:[["From the Sun","0.39 AU (57.9 million km)"],["Diameter","4,879 km"],["A day (sunrise to sunrise)","176 Earth days"],["A year","88 Earth days"],["Gravity","3.7 m/s², 38% of Earth's"],["Temperature","−180 °C at night to 430 °C by day"],["Air","Almost none: a faint trace of oxygen, sodium and helium"],["Moons","None"]],notes:["The smallest planet, and the closest to the Sun.","With no air to hold the heat, its nights are freezing.","There is ice hidden in craters at its poles that sunlight never reaches.","From its surface the Sun looks about three times as wide as it does from Earth."]},{k:"venus",name:"Venus",kind:"The second planet",orbit:1600,ang:2.3,y:-30,r:58,col:15258266,spin:-.004,land:"venus",rows:[["From the Sun","0.72 AU (108.2 million km)"],["Diameter","12,104 km, nearly Earth's size"],["A day (sunrise to sunrise)","117 Earth days"],["One turn on its axis","243 Earth days, longer than its year"],["A year","225 Earth days"],["Gravity","8.9 m/s², 90% of Earth's"],["Temperature","about 465 °C, the hottest planet"],["Air","96.5% carbon dioxide; clouds of sulphuric acid; 92 times Earth's pressure"],["Moons","None"]],notes:["It spins backwards, so the Sun rises in the west and sets in the east.","Its thick carbon dioxide air traps heat: a runaway greenhouse effect.","It is the brightest planet in Earth's sky, the 'morning star' and 'evening star'.","Standing on the real Venus would crush, cook and choke you; your dream suit lets you see it."]},{k:"earth",name:"Earth",kind:"The third planet: home",orbit:2300,ang:4.1,y:0,r:62,col:3828408,spin:.03,land:"earth",tilt:.41,rows:[["From the Sun","1 AU (149.6 million km)"],["Diameter","12,742 km"],["A day","24 hours"],["A year","365.25 days"],["Gravity","9.8 m/s²"],["Average temperature","about 15 °C"],["Air","78% nitrogen, 21% oxygen, 1% argon and others"],["Moons","1, the Moon"]],notes:["The only world we know of with life.","Water covers about 71% of its surface.","Its tilt of 23.4° gives it seasons.","Its magnetic field shields it from the solar wind and makes the auroras."]},{k:"moon",name:"The Moon",kind:"Earth's moon",parent:"earth",orbit:170,ang:.9,y:12,r:17,col:12104876,spin:0,land:"moon",rows:[["From Earth","384,400 km"],["Diameter","3,474 km, about a quarter of Earth's"],["A day (sunrise to sunrise)","29.5 Earth days"],["Gravity","1.62 m/s², about one sixth of Earth's"],["Temperature","−173 °C at night to 127 °C by day"],["Air","None worth the name"]],notes:["It always shows the same face to Earth: it turns once for every trip round us.","It probably formed about 4.5 billion years ago when a Mars-sized world struck the young Earth.","Apollo 11 landed in the Sea of Tranquillity on 20 July 1969; twelve people walked on the Moon between 1969 and 1972.","With no wind or rain, their footprints are still there.","It drifts about 3.8 cm further from Earth every year."]},{k:"mars",name:"Mars",kind:"The fourth planet",orbit:3100,ang:5.6,y:40,r:34,col:12607546,spin:.03,land:"mars",tilt:.44,rows:[["From the Sun","1.52 AU (227.9 million km)"],["Diameter","6,779 km, about half Earth's"],["A day (a 'sol')","24 hours 37 minutes"],["A year","687 Earth days"],["Gravity","3.7 m/s², 38% of Earth's"],["Temperature","about −63 °C on average"],["Air","95% carbon dioxide, very thin: under 1% of Earth's pressure"],["Moons","2, Phobos and Deimos"]],notes:["It is red because its dust is full of iron oxide: rust.","Olympus Mons is the largest volcano in the Solar System, about 22 km high, two and a half times the height of Everest.","Valles Marineris is a canyon about 4,000 km long.","Its sunsets are blue: the fine dust scatters blue light around the Sun.","The rover Perseverance has explored Jezero Crater since 2021."]},{k:"jupiter",name:"Jupiter",kind:"The fifth planet: a gas giant",orbit:5400,ang:1.2,y:-60,r:200,col:14201994,spin:.06,land:"jupiter",rows:[["From the Sun","5.2 AU (778.5 million km)"],["Diameter","139,820 km: 11 Earths across"],["A day","9 hours 56 minutes, the shortest of any planet"],["A year","11.9 Earth years"],["Gravity","24.8 m/s² at the cloud tops, 2.5 times Earth's"],["Temperature","about −110 °C at the cloud tops"],["Air","About 90% hydrogen and 10% helium"],["Moons","95 known"]],notes:["It has more than twice the mass of all the other planets put together.","The Great Red Spot is a storm wider than Earth that has raged for at least 190 years.","Galileo found its four largest moons in 1610: Io, Europa, Ganymede and Callisto.","Ganymede is the largest moon in the Solar System, bigger than Mercury.","There is no solid ground: you can only float above the clouds."]},{k:"saturn",name:"Saturn",kind:"The sixth planet: the ringed giant",orbit:7400,ang:3,y:80,r:170,col:15126422,spin:.055,land:"saturn",tilt:.47,rows:[["From the Sun","9.5 AU (1.43 billion km)"],["Diameter","116,460 km"],["A day","10 hours 33 minutes"],["A year","29.4 Earth years"],["Gravity","10.4 m/s² at the cloud tops"],["Temperature","about −140 °C at the cloud tops"],["Air","About 96% hydrogen and 3% helium"],["Moons","274 known"]],notes:["Its rings are mostly chunks of water ice, some as small as dust and some as big as houses.","The rings stretch about 280,000 km across but are mostly only about 10 metres thick.","It is the least dense planet: lighter than water for its size.","Its moon Titan has a thick nitrogen sky and lakes of liquid methane.","A six-sided storm, the hexagon, circles its north pole."]},{k:"uranus",name:"Uranus",kind:"The seventh planet: an ice giant",orbit:9500,ang:4.6,y:-40,r:95,col:10410208,spin:-.04,land:"uranus",tilt:1.71,rows:[["From the Sun","19.2 AU (2.87 billion km)"],["Diameter","50,724 km, four Earths across"],["A day","17 hours 14 minutes"],["A year","84 Earth years"],["Gravity","8.7 m/s² at the cloud tops"],["Temperature","about −195 °C; it has the coldest air of any planet"],["Air","Hydrogen, helium and a little methane, which makes it blue-green"],["Moons","29 known"]],notes:["It is tipped right over on its side, 98°, perhaps by a giant collision long ago.","Each pole gets about 42 years of sunlight, then 42 years of darkness.","William Herschel discovered it in 1781, the first planet found with a telescope.","Only one spacecraft has visited: Voyager 2, in 1986."]},{k:"neptune",name:"Neptune",kind:"The eighth planet: an ice giant",orbit:11500,ang:.2,y:60,r:92,col:3825368,spin:.045,land:"neptune",tilt:.49,rows:[["From the Sun","30.1 AU (4.5 billion km)"],["Diameter","49,244 km"],["A day","16 hours 6 minutes"],["A year","165 Earth years"],["Gravity","11.2 m/s² at the cloud tops"],["Temperature","about −200 °C"],["Air","Hydrogen, helium and methane"],["Moons","16 known"]],notes:["Its winds are the fastest in the Solar System, up to about 2,000 km/h.","It was found by mathematics: Urbain Le Verrier worked out where it must be, and Johann Galle saw it there in 1846.","Its big moon Triton orbits backwards and has geysers of nitrogen.","Sunlight takes about four hours to reach it."]},{k:"pluto",name:"Pluto",kind:"The ninth planet",orbit:13600,ang:2,y:1400,r:12,col:14205088,spin:-.01,land:"pluto",rows:[["From the Sun","39.5 AU on average (5.9 billion km)"],["Diameter","2,377 km, smaller than our Moon"],["A day","6.4 Earth days"],["A year","248 Earth years"],["Gravity","0.62 m/s², about one sixteenth of Earth's"],["Temperature","about −230 °C"],["Air","A thin haze of nitrogen, methane and carbon monoxide"],["Moons","5: Charon, Nix, Hydra, Kerberos and Styx"]],notes:["Clyde Tombaugh discovered it in 1930, when he was 24.","Somnucor counts it as the ninth planet; astronomers have called it a dwarf planet since 2006.","Its great pale heart is Tombaugh Regio; the left half, Sputnik Planitia, is a glacier of frozen nitrogen.","Its mountains are made of water ice, frozen as hard as rock.","The New Horizons spacecraft flew past on 14 July 2015 and sent back the first close pictures.","Charon is half Pluto's size; the two swing round a point in the space between them."]},{k:"charon",name:"Charon",kind:"Pluto's largest moon",parent:"pluto",orbit:44,ang:1.5,y:4,r:6,col:11052192,spin:0,rows:[["From Pluto","19,600 km"],["Diameter","1,212 km"],["Day and year","6.4 Earth days: it always shows Pluto the same face, and Pluto shows it the same face back"]],notes:["Its reddish north pole, nicknamed Mordor Macula, is stained by gas that escapes from Pluto."]}];var SP_BY={};SP_BODIES.forEach(function(e){SP_BY[e.k]=e});var SP_SURF={moon:{body:"moon",gravity:1.62,ground:[6183766,10131086],rough:12,craters:90,top:0,low:131588,sun:.95,sunCol:16777215,hemi:.25,hemiCol:9476264,fogD:5e-5,stars:1,sky:[{k:"earth",dir:[.5,.42,-.75],size:360}],site:"apollo",sunDir:[.62,.2,-.4],title:"The Sea of Tranquillity",about:"Apollo 11's landing site. The black sky stays black by day: there is no air to scatter the light."},mars:{body:"mars",gravity:3.71,ground:[9059874,12610112],rough:16,craters:14,top:13148280,low:14727312,sun:.85,sunCol:16771280,hemi:.6,hemiCol:15251600,fogD:9e-4,fog:14198912,stars:0,sky:[{k:"phobos",dir:[-.6,.5,.4],size:26,col:9075306}],site:"jezero",sunDir:[.5,.45,-.6],title:"Jezero Crater",about:"Where the rover Perseverance has been working since 2021. The butterscotch sky comes from fine red dust in the thin air."},mercury:{body:"mercury",gravity:3.7,ground:[5656650,9077370],rough:12,craters:100,top:0,low:197379,sun:1.6,sunCol:16777215,hemi:.2,hemiCol:10526880,fogD:4e-5,stars:1,sky:[{k:"sun",dir:[.3,.35,-.88],size:520}],title:"The Caloris rim",sunDir:[.3,.35,-.88],about:"The Sun is three times the width you know, and with no air the shadows are knife-sharp."},venus:{body:"venus",gravity:8.87,ground:[5915688,9071162],rough:6,craters:0,top:13144106,low:14725192,sun:.5,sunCol:16760928,hemi:.8,hemiCol:15245376,fogD:.012,fog:13142576,stars:0,lightning:true,title:"The plains of Lavinia",about:"Noon here is a dim orange twilight under clouds of sulphuric acid. The air is 92 times as heavy as Earth's and hot enough to melt lead."},jupiter:{body:"jupiter",gravity:24.79,cloud:true,ground:[13148272,15257768],bands:[16050384,10117176,15257768,8014378],top:3824272,low:13153428,sun:.7,sunCol:16773336,hemi:.8,hemiCol:15259840,fogD:45e-5,fog:14206112,stars:.2,sky:[{k:"io",dir:[.6,.5,-.4],size:40,col:15257696},{k:"europa",dir:[-.5,.6,-.5],size:30,col:15261904}],redspot:true,title:"Space Corp Cloud Station Galileo",about:"There is no ground on Jupiter: the station floats on the hydrogen sky above the clouds, and the gravity is two and a half times Earth's."},saturn:{body:"saturn",gravity:10.44,cloud:true,ground:[14205072,15654320],bands:[16049852,12623968,15786164,11045456],top:4876954,low:14470308,sun:.6,sunCol:16774368,hemi:.8,hemiCol:15655112,fogD:45e-5,fog:15259824,stars:.25,rings:true,sky:[{k:"titan",dir:[-.5,.4,.6],size:34,col:14196800}],title:"Space Corp Cloud Station Cassini",about:"Saturn's rings arch across the sky like a bridge of ice. Like Jupiter it has no ground; the station floats above the clouds."},uranus:{body:"uranus",gravity:8.69,cloud:true,ground:[9357520,12117226],bands:[12118254,8042692,11066596,6990004],top:1718872,low:9357524,sun:.35,sunCol:15267071,hemi:.7,hemiCol:11065568,fogD:45e-5,fog:9357524,stars:.5,title:"Space Corp Cloud Station Herschel",about:"The Sun is a dazzling point, 400 times dimmer than at Earth. Methane in the air soaks up red light and leaves this blue-green."},neptune:{body:"neptune",gravity:11.15,cloud:true,ground:[2771640,5929696],bands:[3824336,2902192,4877024,2375834],top:528426,low:3824328,sun:.3,sunCol:14740735,hemi:.7,hemiCol:6982368,fogD:45e-5,fog:3824328,stars:.6,wind:true,sky:[{k:"triton",dir:[.4,.45,.7],size:26,col:14207168}],title:"Space Corp Cloud Station Le Verrier",about:"The fastest winds in the Solar System tear past, about 2,000 km/h. The white streaks are clouds of frozen methane."},pluto:{body:"pluto",gravity:.62,ground:[13154472,15261912],rough:5,craters:6,cells:true,top:131848,low:1581102,sun:.35,sunCol:16773344,hemi:.35,hemiCol:8951992,fogD:2e-4,stars:1,sky:[{k:"charon",dir:[-.45,.4,-.8],size:150},{k:"sunstar",dir:[.6,.2,.5],size:14,col:16777200}],haze:true,sunDir:[.6,.2,.5],title:"Sputnik Planitia, the heart of Pluto",about:"A plain of frozen nitrogen, broken into great cells by slow heat from below. The Sun is only a very bright star; at noon it is as light as a dim evening on Earth. Mountains of water ice ring the plain."},veyar:{body:null,gravity:7.2,ground:[3811930,6965898],rough:12,craters:0,top:2755146,low:13134504,sun:.75,sunCol:16763120,hemi:.8,hemiCol:15247592,fogD:.0012,fog:11033240,stars:.3,sky:[{k:"sun2",dir:[.5,.3,-.7],size:140,col:16756960},{k:"sun3",dir:[.62,.42,-.55],size:70,col:10545407}],alien:true,sunDir:[.5,.3,-.7],title:"Veyar, beyond the Far Gate",about:"The home of the Veyari, beneath two suns: a rose one and a little blue one. Nothing in our Solar System looks like this."}};
